function persistLocal(){try{const activeProject=projects.find(project=>project.project_id===(state.projectId||'default'));if(activeProject){activeProject.requirement_count=(state.requirements||[]).length;activeProject.task_count=(state.tasks||[]).length}localStorage.setItem(projectStateKey(state.projectId),JSON.stringify(state));localStorage.setItem('zhidian-active-project',state.projectId||'default');if(state.projectId==='default')localStorage.setItem('zhidian-demo-v1',JSON.stringify(state))}catch{}}
function apiUrl(path,projectId=state.projectId||'default'){return `${path}${path.includes('?')?'&':'?'}project_id=${encodeURIComponent(projectId)}`}
async function apiFetch(input,options={}){const method=String(options.method||'GET').toUpperCase(),writesState=['POST','PUT','PATCH','DELETE'].includes(method);if(writesState){stateWriteRevision++;stateWritesInFlight++}try{return await window.fetch(input,options)}finally{if(writesState)stateWritesInFlight--}}
function persist(){persistLocal();if(serverReady){const projectId=state.projectId||'default',snapshot=JSON.stringify({state:structuredClone(state)});clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{saveTimer=null;saveInFlight=true;try{const response=await apiFetch(apiUrl('/api/state',projectId),{method:'PUT',headers:{'Content-Type':'application/json'},body:snapshot});if(!response.ok)throw new Error('state save failed')}catch{serverReady=false;state.runtimeMode='offline';render()}finally{saveInFlight=false}},180)}}
