function persistRender(){persist();render()}
async function syncOfflineDecisions(projectId,localState,remoteState){
 const queue=[...(localState.pendingServerActions||[])].filter(action=>['requirement_decision','requirement_revision'].includes(action?.type));
 const byRequirement=new Set(queue.map(action=>action.requirementId));
 const localRequirements=localState.requirements||[],remoteRequirements=remoteState.requirements||[];
 // Upgrade decisions made by older offline clients, which did not keep an explicit queue.
 for(const req of localRequirements){
  const decision=req.humanDecision||(['已确认','已拒绝','已搁置','挂起待证据'].includes(req.state)?req.state:null);
  const remoteReq=remoteRequirements.find(item=>item.id===req.id||item.draftId===req.id);
  if(decision&&req.humanDecisionAt&&remoteReq?.state==='待你裁决'&&!byRequirement.has(req.id)){
   queue.push({type:'requirement_decision',requirementId:req.id,decision,note:req.approvalNote||req.decisionNote||'用户在需求工作台确认',createdAt:req.humanDecisionAt});
   byRequirement.add(req.id);
  }
 }
 const remaining=[];let synced=0;
 for(const action of queue){
  let remoteReq=(remoteState.requirements||[]).find(item=>item.id===action.requirementId||item.draftId===action.requirementId);
  if(action.type==='requirement_revision'&&remoteReq?.lastRevisionActionId===action.payload?.action_id){synced++;continue}
  if(action.type==='requirement_decision'&&remoteReq?.state===action.decision){synced++;continue}
  if(!remoteReq||!['待你裁决','挂起待证据'].includes(remoteReq.state)){remaining.push(action);continue}
  const approved=action.type==='requirement_decision'&&action.decision==='已确认';
  const path=action.type==='requirement_revision'?`/api/requirements/${encodeURIComponent(remoteReq.id)}/revise`:approved?`/api/requirements/${encodeURIComponent(remoteReq.id)}/approve`:`/api/requirements/${encodeURIComponent(remoteReq.id)}/decision`;
  const payload=action.type==='requirement_revision'?action.payload:approved?{note:action.note||'用户在需求工作台确认'}:{decision:action.decision,note:action.note||''};
  try{
   const response=await apiFetch(apiUrl(path,projectId),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
   if(!response.ok){
    if(response.status===409){const latestResponse=await apiFetch(apiUrl('/api/state',projectId));const latest=latestResponse.ok?await latestResponse.json():remoteState;const latestReq=(latest.requirements||[]).find(item=>item.id===action.requirementId||item.draftId===action.requirementId);if(action.type==='requirement_revision'&&latestReq?.lastRevisionActionId===action.payload?.action_id||action.type==='requirement_decision'&&latestReq?.state===action.decision){remoteState=latest;synced++;continue}remoteState=latest}
    remaining.push(action);continue
   }
   remoteState=(await response.json()).state||remoteState;synced++;
  }catch{remaining.push(action)}
 }
 if(synced){const latestResponse=await apiFetch(apiUrl('/api/state',projectId));if(latestResponse.ok)remoteState=await latestResponse.json()}
 return {remoteState,remaining,synced};
}
async function initializeBackend(){
 if(backendInitInFlight)return;
 backendInitInFlight=true;clearTimeout(saveTimer);
 try{
  const localState=structuredClone(state),healthResponse=await apiFetch('/api/health');if(!healthResponse.ok)throw new Error('backend unavailable');const health=await healthResponse.json();
  const projectResponse=await apiFetch('/api/projects');if(!projectResponse.ok)throw new Error('project list unavailable');projects=await projectResponse.json();if(!projects.length)throw new Error('no projects');
  const active=projects.find(p=>p.project_id===localState.projectId)||projects.find(p=>p.project_id==='default')||projects[0];
  const response=await apiFetch(apiUrl('/api/state',active.project_id));if(!response.ok)throw new Error('state unavailable');let remote=await response.json();const hadRemote=Object.keys(remote||{}).length>0;
  let remaining=localState.pendingServerActions||[],synced=0;
  if(hadRemote&&active.project_id===localState.projectId){const result=await syncOfflineDecisions(active.project_id,localState,remote);remote=result.remoteState;remaining=result.remaining;synced=result.synced}
  const sameProject=active.project_id===localState.projectId;
  if(hadRemote){state={...localState,...remote,projectId:active.project_id,projectName:active.name,productShape:active.product_shape,mode:active.development_mode,view:sameProject?localState.view:(remote.view||'overview'),activeChat:sameProject?localState.activeChat:(remote.activeChat||'group'),search:localState.search,pendingServerActions:remaining};}
  else{state={...localState,projectId:active.project_id,projectName:active.name,productShape:active.product_shape,mode:active.development_mode,pendingServerActions:remaining}}
  serverReady=true;runtimeAvailability=health.external_runtimes||{};state.runtimeMode=health.agent_configured?'live':'waiting';
  if(!hadRemote)await apiFetch(apiUrl('/api/state',active.project_id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state})});
  persistLocal();render();if(synced)toast(`已自动补同步 ${synced} 条离线裁决`);
 }catch{serverReady=false;state.runtimeMode='offline';render()}
 finally{backendInitInFlight=false}
}
async function refreshBackendState(){
 if(!serverReady||backendInitInFlight||backendRefreshInFlight||saveTimer||saveInFlight||stateWritesInFlight)return;
 backendRefreshInFlight=true;
 const writeRevisionAtStart=stateWriteRevision;
 try{
  const projectId=state.projectId||'default',response=await apiFetch(apiUrl('/api/state',projectId));
  if(!response.ok)throw new Error('state refresh failed');
  const remote=await response.json();if(projectId!==(state.projectId||'default')||stateWritesInFlight||writeRevisionAtStart!==stateWriteRevision)return;
  const localOnly=['view','activeChat','search','runtimeMode','filterKano','filterReqState','reqPage','taskFilterRole','taskFilterRequirement','pendingServerActions'];
  const keys=new Set([...Object.keys(state),...Object.keys(remote)]);let changed=false;
  for(const key of keys){if(localOnly.includes(key))continue;if(JSON.stringify(state[key])!==JSON.stringify(remote[key])){changed=true;break}}
  if(!changed)return;
  const preferences=Object.fromEntries(localOnly.map(key=>[key,state[key]]));
  state={...remote,...preferences,projectId,runtimeMode:state.runtimeMode};
  persistLocal();
  if(modal?.requirementId)requirementDetailModal(modal.requirementId);else render();
 }catch{serverReady=false;state.runtimeMode='offline';render()}
 finally{backendRefreshInFlight=false}
}
async function chooseProject(projectId){const project=projects.find(item=>item.project_id===projectId);if(!project)return;try{const response=await apiFetch(apiUrl('/api/state',projectId));if(!response.ok)throw new Error('读取项目失败');const remote=await response.json();if(!Object.keys(remote||{}).length)throw new Error('项目状态不存在');clearTimeout(saveTimer);state={...structuredClone(seed),...remote,projectId,projectName:project.name,productShape:project.product_shape,mode:project.development_mode,view:'overview',activeChat:'group',search:'',runtimeMode:state.runtimeMode};modal=null;persistLocal();render();toast(`已切换到「${project.name}」`)}catch(error){toast(error.message||'项目切换失败')}}
async function createProject(form){if(!serverReady){toast('服务端当前不可用，暂时无法创建项目');return}const data=new FormData(form);const payload={name:String(data.get('name')||'').trim(),description:String(data.get('description')||'').trim(),product_shape:String(data.get('product_shape')||'待确定'),development_mode:String(data.get('development_mode')||'敏捷迭代')};if(!payload.name){toast('先填写项目名称');return}try{const response=await apiFetch('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.detail||'创建项目失败');projects.unshift(result.project);state={...structuredClone(seed),...result.state,runtimeMode:state.runtimeMode};modal=null;persistLocal();render();toast('项目空间已建立，初始构想与 9 份项目文档已就绪')}catch(error){toast(error.message||'创建项目失败')}}
async function toggleAutoMeetings(){if(!serverReady){toast('项目服务端不可用，会议设置未保存');return}const enabled=!state.meetingEnabled;try{const response=await apiFetch(apiUrl('/api/meetings/config'),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled,cadence:state.cadence,agenda:state.meetingAgenda})}),data=await response.json();if(!response.ok)throw new Error(data.detail||'会议设置保存失败');state.meetingEnabled=data.enabled;state.cadence=data.cadence;state.meetingAgenda=data.agenda||state.meetingAgenda;persistLocal();render();toast(state.meetingEnabled?(state.runtimeMode==='live'?`自动会议已开启，每 ${state.cadence} 分钟运行一轮`:'设置已保存；配置模型密钥后才会实际运行会议'):'自动会议已暂停')}catch(error){toast(error.message||'会议设置未保存')}}
function meetingStartModal(){const agenda=(state.meetingAgenda||seed.meetingAgenda).join('\n');openModal(`${modalHeader('发起项目会议','明确本轮主题和议程；角色按顺序汇报，PM 生成纪要与待确认行动项。')}<form id="meeting-start-form"><div class="modal-body"><div class="field"><label>会议主题 *</label><input name="topic" required minlength="3" maxlength="240" value="项目进展与阻塞"></div><div class="field"><label>本轮议程 · 每行一项</label><textarea name="agenda" required maxlength="3000" style="min-height:120px">${escapeHtml(agenda)}</textarea><span class="field-help">议程会作为角色发言上下文保存；最多 10 项。AI 建议的行动项不会自动创建任务。</span></div><div class="detail-callout">会议会依次调用 PDT、当前任务相关角色、系统工程师和测试工程师，最后由 PM 汇总。需要 Deep Agents 模型已配置。</div></div><footer class="modal-footer"><button type="button" class="btn" data-action="close-modal">取消</button><button type="submit" class="btn primary">开始会议</button></footer></form>`,true)}
async function runLiveMeeting(form){if(!serverReady){toast('项目服务端不可用，会议未发起');return}const fd=new FormData(form),topic=String(fd.get('topic')||'').trim(),agenda=String(fd.get('agenda')||'').split(/\r?\n/).map(item=>item.trim()).filter(Boolean).slice(0,10);if(topic.length<3||!agenda.length){toast('请填写会议主题和至少一条议程');return}const button=form.querySelector('button[type="submit"]');if(button){button.disabled=true;button.textContent='角色正在依序汇报，请稍候…'}try{const response=await apiFetch(apiUrl('/api/meetings/run'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic,agenda})}),data=await response.json();if(!response.ok)throw new Error(data.detail?.message||data.detail||'会议运行失败');const view=state.view,activeChat=state.activeChat;state={...state,...data.state,view,activeChat,runtimeMode:state.runtimeMode};state.meetingAgenda=agenda;modal=null;persistLocal();render();const index=state.meetings.findIndex(m=>m.id===data.meeting?.id);if(index>=0)openMeetingNotes(index);toast(data.meeting?.state==='纪要已生成'?'项目会议已结束，行动项等待项目确认':'会议已部分完成，请检查失败角色与 PM 纪要')}catch(error){if(button){button.disabled=false;button.textContent='开始会议'}toast(error.message||'会议运行失败')}}
async function promoteMeetingAction(el){if(!serverReady){toast('项目服务端不可用，行动项未转任务');return}const meeting=el.dataset.meeting,action=el.dataset.actionId;try{const response=await apiFetch(apiUrl(`/api/meetings/${encodeURIComponent(meeting)}/actions/${encodeURIComponent(action)}/task`),{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.detail||'行动项无法转为任务');const view=state.view,activeChat=state.activeChat;state={...state,...data.state,view,activeChat,runtimeMode:state.runtimeMode};persistLocal();render();const index=state.meetings.findIndex(item=>item.id===meeting);if(index>=0)openMeetingNotes(index);toast(data.idempotent?'此行动项已关联任务':'行动项已确认并加入任务清单')}catch(error){toast(error.message||'行动项转任务失败')}}
function appendLocalDecision(req,decision,note){
 const summary=`用户将 ${req.id} 裁决为${decision}`;
 updateDocs(['doc-1','doc-2','doc-9']);
 for(const doc of state.docs.filter(d=>['doc-1','doc-2','doc-9'].includes(d.id))){
  doc.lastChange=summary;
  const marker=`### ${req.id} · ${decision}`;
  if(!doc.content)doc.content=`# ${doc.name}\n`;
  if(!doc.content.includes(marker)){const section=doc.content.includes('## 用户裁决记录')?'':'\n## 用户裁决记录\n';doc.content+=`${section}\n${marker}\n\n- 需求：${req.title}\n- 裁决时间：${new Date().toISOString()}\n- 裁决理由：${note||'（未提供）'}\n`}
 }
}
function localRequirementSnapshot(req){return Object.fromEntries(['title','subtitle','rationality','kano','why','value','evidence','evidenceLevel','evidenceGap','confidence','priority'].map(key=>[key,req[key]]))}
function appendLocalRequirementHistory(req,action,note,before){req.decisionHistory||=[];req.decisionHistory.push({action,actor:'项目发起人',createdAt:new Date().toISOString(),note,before,after:localRequirementSnapshot(req),draftVersion:req.draftVersion||1,baselineVersion:req.baselineVersion})}
function applyOfflineRequirementDecision(req,decision,note){
 const before=localRequirementSnapshot(req);
 req.state=decision;req.owner='PDT 经理';req.humanDecision=decision;req.humanDecisionAt=new Date().toISOString();req.decisionNote=note;
 appendLocalRequirementHistory(req,decision,note,before);
 state.pendingServerActions||=[];state.pendingServerActions.push({type:'requirement_decision',requirementId:req.id,decision,note,createdAt:req.humanDecisionAt});
 appendLocalDecision(req,decision,note);
 const verb=decision==='已拒绝'?'拒绝':decision==='挂起待证据'?'挂起待证据':'搁置';
 state.chats.group.push({from:'PDT 经理',who:'PDT',color:'#7666db',time:'刚刚',text:`用户已${verb} ${req.id}「${req.title}」。理由：${note}`});
}
async function approveRequirement(reqId,note){
 const req=state.requirements.find(r=>r.id===reqId);if(!req)return;
 if(!['待你裁决','挂起待证据'].includes(req.state)){toast('只有待裁决或挂起待证据的需求可以确认');return}
 if(serverReady){
  try{const response=await apiFetch(apiUrl(`/api/requirements/${encodeURIComponent(reqId)}/approve`),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note})});const data=await response.json();if(!response.ok)throw new Error(data.detail||'需求裁决保存失败');const view=state.view;state={...state,...data.state,view,activeChat:state.activeChat,runtimeMode:state.runtimeMode};modal=null;persistLocal();render();toast(`${data.draft_id} 已形成正式基线 ${data.requirement.id} v${data.requirement.baselineVersion}；PM 已进入自动拆解队列`);return}catch(error){if(error instanceof TypeError){serverReady=false;state.runtimeMode='offline';const before=localRequirementSnapshot(req);req.state='已确认';req.owner='PDT 经理';req.humanDecision='已确认';req.humanDecisionAt=new Date().toISOString();req.decisionNote=note;req.approvalNote=note;req.baselinePendingSync=true;appendLocalRequirementHistory(req,'批准',note,before);state.pendingServerActions||=[];state.pendingServerActions.push({type:'requirement_decision',requirementId:req.id,decision:'已确认',note,createdAt:req.humanDecisionAt});appendLocalDecision(req,'已确认纳入范围',note);state.chats.group.push({from:'PDT 经理',who:'PDT',color:'#7666db',time:'刚刚',text:`${req.id} 已由你确认，裁决待服务端同步；正式需求编号和 PM 拆解将在恢复连接后生成。理由：${note}`});modal=null;persistRender();toast('网络中断，裁决已本地保存；正式基线会在重连后生成');return}toast(String(error.message||error));return}
 }
 const before=localRequirementSnapshot(req);req.state='已确认';req.owner='PDT 经理';req.humanDecision='已确认';req.humanDecisionAt=new Date().toISOString();req.decisionNote=note;req.approvalNote=note;req.baselinePendingSync=true;appendLocalRequirementHistory(req,'批准',note,before);
 state.pendingServerActions||=[];state.pendingServerActions.push({type:'requirement_decision',requirementId:req.id,decision:'已确认',note,createdAt:req.humanDecisionAt});
 appendLocalDecision(req,'已确认纳入范围',note);
 state.chats.group.push({from:'PDT 经理',who:'PDT',color:'#7666db',time:'刚刚',text:`${req.id} 已由你确认，裁决待服务端同步；正式需求编号和 PM 拆解将在恢复连接后生成。理由：${note}`});
 modal=null;persistRender();toast('裁决已本地保存，连接恢复后会生成正式基线并派发 PM 拆解')
}
