function markdownSource(value){
 if(value==null)return '';
 if(typeof value==='string')return value;
 if(typeof value==='number'||typeof value==='boolean')return String(value);
 if(Array.isArray(value))return value.map(item=>typeof item==='string'?item:typeof item?.text==='string'?item.text:typeof item?.content==='string'?item.content:item&&typeof item==='object'?markdownSource(item):JSON.stringify(item)).filter(Boolean).join('\n\n');
 if(typeof value==='object'){
  if(typeof value.text==='string')return value.text;
  if(typeof value.content==='string'||Array.isArray(value.content))return markdownSource(value.content);
  if(typeof value.summary==='string')return value.summary;
  return '```json\n'+JSON.stringify(value,null,2)+'\n```';
 }
 return String(value);
}
function markdownHref(raw){try{const url=new URL(String(raw).trim());return ['http:','https:','mailto:'].includes(url.protocol)?url.href:null}catch{return null}}
function markdownImageHref(raw){try{const url=new URL(String(raw).trim(),window.location.href);return ['http:','https:'].includes(url.protocol)?url.href:null}catch{return null}}
function markdownInline(value){
 const parts=[];const token=html=>{const index=parts.push(html)-1;return `\uE000${index}\uE001`};
 let source=markdownSource(value).replace(/\\([\\`*_{}\[\]()#+.!>|~-])/g,(_,character)=>token(escapeHtml(character)));
 source=source.replace(/(`+)([^\n]*?[^`])\1(?!`)/g,(_,ticks,code)=>token(`<code>${escapeHtml(code.trim())}</code>`));
 source=source.replace(/!\[([^\]]*)\]\(\s*(<[^>]+>|[^\s)]+)(?:\s+(["'][^"']*["']))?\s*\)/g,(_,alt,rawHref)=>{const href=markdownImageHref(rawHref.replace(/^<|>$/g,''));return href?token(`<img src="${escapeHtml(href)}" alt="${escapeHtml(alt)}" loading="lazy" referrerpolicy="no-referrer">`):(alt||'图片')});
 source=source.replace(/\[([^\]]+)\]\(\s*(<[^>]+>|[^\s)]+)(?:\s+(["'][^"']*["']))?\s*\)/g,(_,label,rawHref)=>{const href=markdownHref(rawHref.replace(/^<|>$/g,''));return href?token(`<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`):`${label} (${rawHref})`});
 source=source.replace(/<((?:https?:\/\/|mailto:)[^ >]+)>/g,(_,rawHref)=>{const href=markdownHref(rawHref);return href?token(`<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(rawHref)}</a>`):rawHref});
 source=source.replace(/(^|\s)(https?:\/\/[^\s<]+)/g,(_,prefix,rawHref)=>{const trailing=(rawHref.match(/[),.!?;:]+$/)||[''])[0],label=rawHref.slice(0,rawHref.length-trailing.length),href=markdownHref(label);return href?`${prefix}${token(`<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`)}${trailing}`:`${prefix}${rawHref}`});
 source=source.replace(/(^|\s)([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})(?=$|\s)/gi,(_,prefix,email)=>`${prefix}${token(`<a href="mailto:${escapeHtml(email)}">${escapeHtml(email)}</a>`)}`);
 let html=escapeHtml(source)
  .replace(/(^|[^\\])\*\*(?=\S)(.+?\S)\*\*(?!\*)/g,'$1<strong>$2</strong>')
  .replace(/(^|[^\\])__(?=\S)(.+?\S)__(?!_)/g,'$1<strong>$2</strong>')
  .replace(/~~(?=\S)(.+?\S)~~/g,'<del>$1</del>')
  .replace(/(^|[^\\*])\*(?=\S)(.+?\S)\*(?!\*)/g,'$1<em>$2</em>')
  .replace(/(^|[^\\_])_(?=\S)(.+?\S)_(?!_)/g,'$1<em>$2</em>');
 return html.replace(/\uE000(\d+)\uE001/g,(_,index)=>parts[Number(index)]||'');
}
function markdownText(value){return markdownInline(value).replace(/<[^>]*>/g,'')}
function markdownTableCells(line){return line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(cell=>cell.trim())}
function markdownList(lines,start){
 const first=lines[start].match(/^(\s*)([-*+]|\d+\.)\s+(.+)$/);if(!first)return null;
 const indentOf=value=>value.replace(/\t/g,'    ').length,baseIndent=indentOf(first[1]),ordered=/^\d/.test(first[2]);let index=start;const items=[];
 while(index<lines.length){
  if(!lines[index].trim()){let look=index+1;while(look<lines.length&&!lines[look].trim())look++;const next=lines[look]?.match(/^(\s*)([-*+]|\d+\.)\s+(.+)$/),nextIndent=next?indentOf(next[1]):-1,nextOrdered=next?/^\d/.test(next[2]):false;if(items.length&&next&&((nextIndent===baseIndent&&nextOrdered===ordered)||nextIndent>baseIndent)){index=look}else break}
  const match=lines[index].match(/^(\s*)([-*+]|\d+\.)\s+(.+)$/);if(!match)break;
  const indent=indentOf(match[1]),isOrdered=/^\d/.test(match[2]);if(indent<baseIndent)break;
  if(indent>baseIndent){if(!items.length)break;const nested=markdownList(lines,index);if(!nested)break;items[items.length-1].children.push(nested.html);index=nested.next;continue}
  if(isOrdered!==ordered)break;
  const check=match[3].match(/^\[([ xX])\]\s+(.+)$/);items.push({body:check?`<input type="checkbox" disabled ${check[1].toLowerCase()==='x'?'checked':''}>${markdownInline(check[2])}`:markdownInline(match[3]),checked:!!check,children:[]});index++;
 }
 const tag=ordered?'ol':'ul';return{html:`<${tag}>${items.map(item=>`<li${item.checked?' class="task-list-item"':''}>${item.body}${item.children.join('')}</li>`).join('')}</${tag}>`,next:index}
}
function markdownBlockStart(lines,index){const line=lines[index]||'';return /^\s*(?:```|~~~)/.test(line)||/^\s{0,3}#{1,6}\s+/.test(line)||/^\s*>/.test(line)||/^\s*(?:[-*+]\s+|\d+\.\s+)/.test(line)||/^\s*(?:---+|___+|\*\*\*+)\s*$/.test(line)||(line.includes('|')&&index+1<lines.length&&markdownTableCells(lines[index+1]).length>1&&markdownTableCells(lines[index+1]).every(cell=>/^:?-{3,}:?$/.test(cell)))}
function renderMarkdown(value){
 const lines=markdownSource(value).replace(/\r\n?/g,'\n').split('\n'),blocks=[];let i=0;
 while(i<lines.length){
  const line=lines[i];if(!line.trim()){i++;continue}
  const fence=line.match(/^\s*(```+|~~~+)\s*([\w+-]*)[^\n]*$/);
  if(fence){const body=[];i++;while(i<lines.length&&!new RegExp(`^\\s*${fence[1][0]}{${fence[1].length},}\\s*$`).test(lines[i]))body.push(lines[i++]);if(i<lines.length)i++;const language=/^[\w+-]{1,24}$/.test(fence[2])?` class="language-${fence[2]}"`:'';blocks.push(`<pre><code${language}>${escapeHtml(body.join('\n'))}</code></pre>`);continue}
  const heading=line.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);if(heading){const level=heading[1].length;blocks.push(`<h${level}>${markdownInline(heading[2])}</h${level}>`);i++;continue}
  if(i+1<lines.length&&/^\s*(?:===+|---+)\s*$/.test(lines[i+1])){const level=lines[i+1].trim().startsWith('=')?1:2;blocks.push(`<h${level}>${markdownInline(line.trim())}</h${level}>`);i+=2;continue}
  if(/^\s*(?:---+|___+|\*\*\*+)\s*$/.test(line)){blocks.push('<hr>');i++;continue}
  if(/^\s*>/.test(line)){const quote=[];while(i<lines.length&&/^\s*>/.test(lines[i]))quote.push(lines[i++].replace(/^\s*>\s?/,''));blocks.push(`<blockquote>${renderMarkdown(quote.join('\n'))}</blockquote>`);continue}
  const listMatch=line.match(/^\s*([-*+]|\d+\.)\s+(.+)$/);if(listMatch){const list=markdownList(lines,i);if(list&&list.next>i){blocks.push(list.html);i=list.next;continue}}
  if(line.includes('|')&&i+1<lines.length){const headers=markdownTableCells(line),divider=markdownTableCells(lines[i+1]);if(headers.length>1&&divider.length===headers.length&&divider.every(cell=>/^:?-{3,}:?$/.test(cell))){i+=2;const rows=[];while(i<lines.length&&lines[i].includes('|')&&lines[i].trim()){const cells=markdownTableCells(lines[i]);rows.push(`<tr>${headers.map((_,column)=>`<td>${markdownInline(cells[column]||'')}</td>`).join('')}</tr>`);i++}blocks.push(`<div class="md-table-wrap"><table><thead><tr>${headers.map(cell=>`<th>${markdownInline(cell)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`);continue}}
  const paragraph=[line.trim()];i++;while(i<lines.length&&lines[i].trim()&&!markdownBlockStart(lines,i)){paragraph.push(lines[i].trim());i++}blocks.push(`<p>${paragraph.map(markdownInline).join('<br>')}</p>`);
 }
 return blocks.join('');
}
function markdownBlock(value,className=''){return `<div class="markdown-body${className?` ${className}`:''}">${renderMarkdown(value)}</div>`}
function messageHtml(m){const body=m.text??m.content??'';if(m.system)return `<div class="message-system markdown-body">${renderMarkdown(body)}</div>`;let mine=m.mine;return `<div class="message ${mine?'mine':''}"><div class="message-avatar" style="background:${mine?'#bd9773':m.color}">${mine?'Z':escapeHtml(m.who)}</div><div class="message-body"><div class="message-meta">${mine?'张同学':escapeHtml(m.from)}<span>${escapeHtml(m.time)}</span></div><div class="message-bubble markdown-body">${renderMarkdown(body)}</div></div></div>`}

